/**
 * Class CFS_Icons
 *
 * Icons are returned as bare <svg> strings with no wrapper element: the CSS
 * targets them through the parent selector (.cfs-field--has-icon > svg,
 * .cfs-btn--submit > svg), so adding a <span> around one breaks the styling.
 *
 * Each icon should carry width="24" height="24" and use currentColor so it
 * inherits the field colour on focus and error.
 *
 * Add icons without touching the plugin:
 *
 *   add_filter( 'cfs_icon_library', function ( array $icons ): array {
 *       $icons['rocket'] = '<svg …>…</svg>';
 *       return $icons;
 *   } );
 */
class CFS_Icons {

	/**
	 * Cached library.
	 *
	 * @var array<string, string>|null
	 */
	private static $library = null;

	/**
	 * The full icon library.
	 *
	 * @return array<string, string> Icon key => SVG markup.
	 */
	public static function library(): array {
		if ( null !== self::$library ) {
			return self::$library;
		}

