		/**
		 * Filter the icon library.
		 *
		 * @param array<string, string> $icons Icon key => SVG markup.
		 */
		self::$library = (array) apply_filters( 'cfs_icon_library', $icons );

		return self::$library;
	}

	/**
	 * Render one icon, or an empty string when the key is unknown.
	 *
	 * Callers never need to check the result — an unknown icon simply renders
	 * nothing rather than breaking the field.
	 *
	 * @param string $name Icon key.
	 * @return string SVG markup or ''.
	 */
	public static function render( string $name ): string {
		$name = trim( $name );
		if ( '' === $name ) {
			return '';
		}

		$library = self::library();

		return isset( $library[ $name ] ) ? (string) $library[ $name ] : '';
	}

	/**
	 * Icon keys, for the tag generator dropdown.
	 *
	 * @return string[]
	 */
	public static function keys(): array {
		return array_keys( self::library() );
	}

	/**
	 * Reset the cached library (used by tests).
	 */
	public static function flush_cache(): void {
		self::$library = null;
	}
}
